# owner: platform
"""Contact sheet for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def contact_rows(
    students: Iterable[Student]
) -> List[str]:
    """Name, section and email in aligned columns."""
    roster = sorted(
        students, key=lambda item: item.display_name
    )
    if not roster:
        raise ProjectError("no students for contact sheet")
    for item in roster:
        if not item.email:
            raise ProjectError(
                f"no email for {item.display_name}"
            )
    wide_name = max(len(i.display_name) for i in roster)
    wide_sect = max(len(i.section) for i in roster)
    return [
        f"{i.display_name:<{wide_name}}  "
        f"{i.section:<{wide_sect}}  {i.email}"
        for i in roster
    ]
